var sp = APP.el('sp'), tm = APP.el('tm');
function draw() {
  var v = +sp.value, t = +tm.value, d = v * t;
  APP.el('spv').textContent = v; APP.el('tmv').textContent = t; APP.el('dist').textContent = d;
  APP.el('bar').style.width = Math.round(d / 600 * 100) + '%';
}
sp.addEventListener('input', draw); tm.addEventListener('input', draw);
APP.el('rand').addEventListener('click', function () {
  var v = 2 + Math.floor(Math.random() * 20), t = 2 + Math.floor(Math.random() * 10);
  APP.el('quiz').textContent = '속력 ' + v + ' m/s로 ' + t + '초 동안 가면 몇 m일까요? (정답: ' + (v * t) + ' m)';
});
APP.onReset(function () { APP.el('quiz').textContent = ''; draw(); });
draw();
